mapper.select:
	  	SELECT ctrl_device_id,
			device_identifier,
			device_type,
			digital_twin_id,
			digital_object_id,
			protocol_type,
			ipAddr,
			port
		FROM ctrl_device_info
  		WHERE 1=1 AND device_status = 'Y'	

  			 AND ctrl_device_id = #{ctrlDeviceId}


  		 	AND device_identifier = #{deviceIdentifier}


  			 AND device_type = #{deviceType}


  			 AND digital_twin_id = #{digitalTwinId}


  			 AND digital_object_id = #{digitalObjectId}


  			 AND protocol_type = #{protocolType}


  			 AND ipAddr = #{ipAddr}

  		ORDER BY ctrl_device_id

  		 	LIMIT #{start},#{end}


	  	SELECT ctrl_device_id,
			device_identifier,
			device_type,
			device_status,
			digital_twin_id,
			digital_object_id,
			protocol_type,
			ipAddr,
			port
		FROM ctrl_device_info
  		WHERE 1=1 AND device_status = 'Y'	

  			 AND ctrl_device_id = #{ctrlDeviceId}


  		 	AND device_identifier = #{deviceIdentifier}


  			 AND device_type = #{deviceType}


  			 AND digital_twin_id = #{digitalTwinId}


  			 AND digital_object_id = #{digitalObjectId}


  			 AND protocol_type = #{protocolType}


